# Lobe Limpet: content for the free revision quiz pages (see build.py).
# Each question: (topic label, question HTML, [options], index of correct option, explanation HTML)
# Check every fact against the exam board specification before publishing.

SCI_CTA = ("Lobe Limpet turns topics like these into short quizzes, flashcards and clear notes, with written answers "
           "marked the way an examiner would. Daily review brings back what you're about to forget, so it sticks for the exam.")
LIT_CTA = ("Lobe Limpet turns texts like this into short quizzes, flashcards and clear notes, with practice written answers "
           "marked the way an examiner would. Daily review brings back the quotes you're about to forget, so they stick for the exam.")

def sci_faq(subject, board_code, papers, p1_topics, p2_topics, extra_q, extra_a, n):
    return [
        (f"What topics are on AQA GCSE {subject} Paper {n}?", p1_topics if n == 1 else p2_topics),
        (f"Is Combined Science Paper {n} the same as {subject} Paper {n}?",
         f"They cover the same main topics, but separate (triple) {subject} has extra content. This page notes which parts are separate {subject} only."),
        (f"How long is the {subject} Paper {n} exam?",
         f"For AQA, separate {subject} Paper {n} is 1 hour 45 minutes and Combined Science: Trilogy {subject} Paper {n} is 1 hour 15 minutes. Check your exam timetable for the exact dates."),
        (extra_q, extra_a),
    ]

SCI_TIPS_BULLETS = [
    "<strong>Quiz first, then check the notes.</strong> Trying to remember is what makes it stick.",
    "<strong>Come back to topics over several days.</strong> Little and often lasts longer than one long session.",
]

